    s.onpointerup = s.onpointercancel = () => { touch.active = false; touch.x = touch.y = 0; };
    function stickMove(e) { const b=s.getBoundingClientRect(), dx=e.clientX-(b.left+b.width/2), dy=e.clientY-(b.top+b.height/2), len=Math.hypot(dx,dy), max=39; touch.x=dx/Math.max(max,len); touch.y=dy/Math.max(max,len); }
    const fire = $('#fire'); fire.onpointerdown = e => { e.preventDefault(); mouse.down=true; };
