(() => {
  const $ = (s) => document.querySelector(s);
  const WORLD = { w: 2400, h: 1600 };
  const canvas = $('#world');
  const ctx = canvas.getContext('2d');
  let W = 0, H = 0, scale = 1, raf = 0, previous = 0;
  let playing = false, paused = false, resultShown = false;
  let elapsed = 0, kills = 0, remainingCount = 0, player, bots = [], shots = [], loot = [];
  let trees = [], buildings = [], roads = [], camera = { x: 1200, y: 800 }, zone = { x: 1200, y: 800, r: 740 };
  const keys = Object.create(null);
  const mouse = { x: 0, y: 0, down: false, moved: false };
  const touch = { active: false, x: 0, y: 0, id: null };
  let toastTimer = 0;

  const rand = (a, b) => a + Math.random() * (b - a);
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  function resize() {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    W = rect.width; H = rect.height;
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    scale = clamp(Math.min(W / 1000, H / 650), .43, 1);
  }
  new ResizeObserver(resize).observe(canvas); resize();

  function makeWorld() {
    trees = []; buildings = []; roads = [];
    const palettes = [['#74816d','#a9a078'],['#687d6a','#9d9874'],['#907d60','#c0a979'],['#65837b','#9eb5a0']];
    for (let i=0;i<42;i++) {
      const x=rand(130,2270), y=rand(120,1480);
      if ((x<570&&y<480)||(x>1810&&y<510)||(x<460&&y>1170)) continue;
      const w=rand(60,125), h=rand(48,100), p=palettes[i%palettes.length];
      buildings.push({x,y,w,h,c:p[0],roof:p[1],tone:i%3});
    }
    for (let i=0;i<190;i++) {
      const x=rand(50,2350), y=rand(55,1545);
      if (buildings.some(b=>Math.abs(x-b.x)<b.w*.7&&Math.abs(y-b.y)<b.h*.7)) continue;
      trees.push({x,y,r:rand(8,19),tone:Math.floor(rand(0,5))});
    }
    roads=[[120,790,2280,790],[740,120,740,1480],[1580,120,1580,1480],[300,440,2100,440],[350,1160,2100,1160]];
  }
  function makeEntity(x,y,isPlayer=false,id=0) {
    return {x,y,hp:100,armor:isPlayer?25:0,alive:true,angle:0,speed:isPlayer?215:rand(92,125),fireCd:rand(.2,1.3),ammo:isPlayer?30:Infinity,reserve:isPlayer?120:0,meds:isPlayer?2:0,reload:0,invuln:0,id,isPlayer};
  }
  function buildUI() {
    $('#gameUI').innerHTML=`
      <div class="hudtop">
        <div class="hudbox healthbox"><div class="hptext" id="hptext">100 HP · 25 ARMOR</div><div class="bar"><i id="hpbar"></i></div><div class="bar armorbar"><i id="armorbar"></i></div></div>
        <div class="hudcenter"><div id="phase">SAFE ZONE</div><strong id="zonetimer">00:25</strong></div>
        <div class="hudbox weaponhud"><b><span id="ammotext">30</span> <small>/ <span id="reserve">120</span></small></b><div>BREAKWATER AR <span id="reloadtext"></span></div></div>
      </div>
      <div class="mapbox"><canvas id="minimap"></canvas></div>
      <div class="hudline"><span>OPERATORS <b id="alive">24</b></span><span>ELIMS <b id="killcount">0</b></span></div>
      <div class="bottomhud"><div class="hudbox itemhud">✚ <b id="medcount">2</b><small> MEDKITS · E</small></div><button class="hudbox action-button" id="reloadBtn">R RELOAD</button><button class="hudbox action-button leave-match" id="leave">⏸ PAUSE</button></div>
      <div class="mobile-tip">WASD / ARROWS MOVE · CLICK OR HOLD TO FIRE · R RELOAD · Q MEDKIT · ESC PAUSE</div>
      <div class="touch-controls"><div class="stick-zone" id="stick"><div class="stick-knob" id="knob"></div></div><div class="touch-actions"><button id="fireTouch">FIRE</button><button id="medTouch">MED</button></div></div>
      <div id="toast" class="toast-message"></div><div id="result"></div>`;
    $('#leave').onclick=showPause;
    $('#reloadBtn').onclick=reload;
    $('#fireTouch').onpointerdown=e=>{e.preventDefault();mouse.down=true};
    $('#fireTouch').onpointerup=()=>mouse.down=false;
    $('#fireTouch').onpointercancel=()=>mouse.down=false;
    $('#medTouch').onclick=useMed;
    $('#stick').onpointerdown=startStick;
  }
  function startGame() {
    cancelAnimationFrame(raf);
    $('#modal').classList.add('hidden'); $('#lobby').classList.add('hidden'); $('#game').classList.remove('hidden');
    resize(); buildUI(); makeWorld();
    elapsed=0;kills=0;remainingCount=24;paused=false;resultShown=false;shots=[];loot=[];
    zone={x:1200,y:800,r:740}; player=makeEntity(1200+rand(-210,210),800+rand(-170,170),true);
    bots=[]; for(let i=0;i<23;i++){const a=i/23*Math.PI*2,r=rand(320,680);bots.push(makeEntity(clamp(1200+Math.cos(a)*r,45,2355),clamp(800+Math.sin(a)*r,45,1555),false,i+1));}
    camera={x:player.x,y:player.y}; mouse.down=false; mouse.moved=false; previous=performance.now(); updateHud(); draw(); raf=requestAnimationFrame(loop);
  }
  function loop(now) {
    const dt=Math.min(.05,Math.max(0,(now-previous)/1000)); previous=now;
    update(dt); draw(); if(playing||!resultShown) raf=requestAnimationFrame(loop);
  }
  function moveEntity(ent,dx,dy) {
    const nx=clamp(ent.x+dx,35,WORLD.w-35), ny=clamp(ent.y+dy,35,WORLD.h-35);
    const blocked=buildings.some(b=>nx>b.x-b.w/2-13&&nx<b.x+b.w/2+13&&ny>b.y-b.h/2-13&&ny<b.y+b.h/2+13);
    if(!blocked){ent.x=nx;ent.y=ny;} else {ent.x=clamp(ent.x+dx,35,WORLD.w-35);}
  }
  function worldPoint(x,y) { return {x:(x-W/2)/scale+camera.x,y:(y-H/2)/scale+camera.y}; }
  function nearestOpponent(ent,max=Infinity) {
    let best=null,dist=max;
    for(const o of [player,...bots]) if(o!==ent&&o.alive){const d=Math.hypot(o.x-ent.x,o.y-ent.y);if(d<dist){dist=d;best=o;}}
    return best;
  }
  function shoot(ent,target,accurate) {
    if(!ent.alive||ent.fireCd>0)return;
    if(ent.isPlayer&&ent.ammo<=0){reload();return;}
    ent.fireCd=ent.isPlayer?.16:rand(.48,.82); if(ent.isPlayer)ent.ammo--;
    let angle=ent.angle;
    if(target&&target.alive&&!ent.isPlayer) angle=Math.atan2(target.y-ent.y,target.x-ent.x)+rand(-.16,.16);
    else if(ent.isPlayer&&!mouse.moved&&target&&target!==player) angle=Math.atan2(target.y-ent.y,target.x-ent.x);
    else if(ent.isPlayer&&mouse.moved){const p=worldPoint(mouse.x,mouse.y);angle=Math.atan2(p.y-ent.y,p.x-ent.x);}
    else angle+=rand(-.055,.055);
    ent.angle=angle;
    const range=ent.isPlayer?670:490;
    shots.push({x:ent.x+Math.cos(angle)*15,y:ent.y+Math.sin(angle)*15,vx:Math.cos(angle)*760,vy:Math.sin(angle)*760,life:range/760,owner:ent,damage:ent.isPlayer?26:10});
  }
  function hit(ent,damage,owner) {
    if(!ent.alive||ent.invuln>0)return;
    const absorbed=Math.min(ent.armor,damage*.65);ent.armor-=absorbed;ent.hp-=damage-absorbed;ent.invuln=.07;
    if(ent.hp<=0){ent.hp=0;ent.alive=false;if(ent===player){endMatch();}else{remainingCount--;if(owner===player)kills++;dropLoot(ent.x,ent.y);}}
  }
  function dropLoot(x,y) {loot.push({x:x+rand(-12,12),y:y+rand(-12,12),type:['ammo','armor','med'][Math.floor(rand(0,3))],taken:false});}
  function toast(text){const el=$('#toast');if(!el)return;el.textContent=text;el.classList.add('show');toastTimer=1.5;}
  function reload(){if(player&&player.ammo<30&&player.reserve>0&&player.reload<=0){player.reload=1.15;mouse.down=false;}}
  function useMed(){if(player&&player.meds>0&&player.hp<100){player.meds--;player.hp=Math.min(100,player.hp+38);toast('MEDKIT USED');updateHud();}}
  function startStick(e){e.preventDefault();const el=$('#stick'),rect=el.getBoundingClientRect();touch.id=e.pointerId;el.setPointerCapture(e.pointerId);updateStick(e,rect);}
  function updateStick(e,rect){const cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,dx=e.clientX-cx,dy=e.clientY-cy,len=Math.hypot(dx,dy),max=39,m=Math.min(1,max/(len||1));touch.x=dx*m/max;touch.y=dy*m/max;touch.active=true;const knob=$('#knob');knob.style.transform=`translate(${touch.x*max}px,${touch.y*max}px)`;}
  document.addEventListener('pointermove',e=>{if(touch.id===e.pointerId)updateStick(e,$('#stick').getBoundingClientRect());});
  document.addEventListener('pointerup',e=>{if(touch.id===e.pointerId){touch.id=null;touch.active=false;touch.x=touch.y=0;const k=$('#knob');if(k)k.style.transform='translate(0,0)';}});
  canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top;if(e.pointerType==='mouse')mouse.moved=true;});
  canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){mouse.down=true;canvas.setPointerCapture(e.pointerId);}});
  window.addEventListener('pointerup',e=>{if(e.pointerType==='mouse')mouse.down=false;});
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'||k==='p')showPause();if(k==='r')reload();if(k==='q'||k==='e')useMed();});
  window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
  window.addEventListener('blur',()=>{mouse.down=false;for(const k in keys)keys[k]=false;});
  $('#start').onclick=startGame;

