function update(dt) {
  if (!playing || paused || resultShown) return;
  elapsed+=dt; player.fireCd=Math.max(0,player.fireCd-dt); player.invuln=Math.max(0,player.invuln-dt);
  if (player.reload>0) {player.reload-=dt;if(player.reload<=0){const take=Math.min(30,player.reserve);player.ammo=take;player.reserve-=take;}}
  let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+(touch.active?touch.x:0);
  let dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+(touch.active?touch.y:0);
  const len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len;}
  if(len>0){moveEntity(player,dx*player.speed*dt,dy*player.speed*dt);if(!mouse.moved)player.angle=Math.atan2(dy,dx);}
  if(mouse.moved){const p=worldPoint(mouse.x,mouse.y);player.angle=Math.atan2(p.y-player.y,p.x-player.x);}
  if(mouse.down){const target=mouse.moved?null:nearestOpponent(player,610);shoot(player,target,true);}
  for(const b of bots){
    if(!b.alive)continue;b.think=(b.think||rand(.1,.4))-dt;b.fireCd=Math.max(0,b.fireCd-dt);
    if(b.think<=0){b.think=rand(.35,.9);b.target=nearestOpponent(b,430);if(b.target)b.angle=Math.atan2(b.target.y-b.y,b.target.x-b.x)+rand(-.3,.3);else b.angle+=rand(-1.3,1.3);}
    const target=b.target&&b.target.alive?b.target:nearestOpponent(b,370),distance=target?Math.hypot(target.x-b.x,target.y-b.y):999;
    if(target&&distance<370){b.angle=Math.atan2(target.y-b.y,target.x-b.x);if(distance>155)moveEntity(b,Math.cos(b.angle)*b.speed*dt,Math.sin(b.angle)*b.speed*dt);if(distance<330)shoot(b,target,false);}
    else{const a=Math.atan2(zone.y-b.y,zone.x-b.x);b.angle=a+Math.sin(elapsed*.7+b.id)*.7;moveEntity(b,Math.cos(b.angle)*b.speed*.42*dt,Math.sin(b.angle)*b.speed*.42*dt);}
  }
  zone.r=Math.max(125,740-Math.max(0,elapsed-25)*1.25);
  for(const ent of [player,...bots])if(ent.alive&&Math.hypot(ent.x-zone.x,ent.y-zone.y)>zone.r){ent.hp-=dt*(ent===player?10:7);if(ent.hp<=0){ent.hp=0;ent.alive=false;if(ent!==player){remainingCount--;dropLoot(ent.x,ent.y);}}}
  for(const l of loot)if(!l.taken&&Math.hypot(player.x-l.x,player.y-l.y)<27){l.taken=true;if(l.type==='med'){if(player.hp<100)player.hp=Math.min(100,player.hp+22);else player.meds=Math.min(4,player.meds+1);toast('PICKED UP MEDKIT');}else if(l.type==='armor'){player.armor=Math.min(100,player.armor+28);toast('PICKED UP ARMOR');}else{player.reserve=Math.min(240,player.reserve+30);toast('PICKED UP AMMO');}}
  for(const s of shots){s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;const targets=s.owner===player?bots:[player,...bots].filter(e=>e!==s.owner);for(const target of targets){if(target.alive&&Math.hypot(target.x-s.x,target.y-s.y)<14){hit(target,s.damage,s.owner);s.life=0;break;}}}
  shots=shots.filter(s=>s.life>0);camera.x+=(player.x-camera.x)*Math.min(1,dt*6);camera.y+=(player.y-camera.y)*Math.min(1,dt*6);
  if(!player.alive||remainingCount<=1)endMatch();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast')?.classList.remove('show');}updateHud();
}
function updateHud(){
  if(!player||!$('#hpbar'))return;
  $('#alive').textContent=remainingCount;$('#killcount').textContent=kills;$('#hpbar').style.width=`${player.hp}%`;$('#armorbar').style.width=`${player.armor}%`;
  $('#hptext').textContent=`${Math.ceil(player.hp)} HP · ${Math.ceil(player.armor)} ARMOR`;
  $('#ammotext').textContent=player.ammo;$('#reserve').textContent=player.reserve;$('#medcount').textContent=player.meds;
  $('#reloadtext').textContent=player.reload>0?'RELOADING…':'';
  const next=Math.max(0,25-elapsed),phase=$('#phase');if(phase){phase.textContent=next>0?'SAFE ZONE':`STORM · ${Math.ceil(zone.r)}M`;phase.classList.toggle('danger',next<=0);}
  $('#zonetimer').textContent=next>0?`00:${String(Math.ceil(next)).padStart(2,'0')}`:'CLOSING';
  const mini=$('#minimap');if(mini){const r=mini.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);if(mini.width!==Math.round(r.width*d)||mini.height!==Math.round(r.height*d)){mini.width=Math.round(r.width*d);mini.height=Math.round(r.height*d);}const m=mini.getContext('2d');m.setTransform(d,0,0,d,0,0);m.clearRect(0,0,r.width,r.height);m.fillStyle='#456552';m.fillRect(0,0,r.width,r.height);m.strokeStyle='#b9eee0';m.lineWidth=1;m.beginPath();m.arc(zone.x/WORLD.w*r.width,zone.y/WORLD.h*r.height,zone.r/WORLD.w*r.width,0,Math.PI*2);m.stroke();for(const b of bots)if(b.alive){m.fillStyle='#ff795f';m.fillRect(b.x/WORLD.w*r.width-1,b.y/WORLD.h*r.height-1,3,3);}m.fillStyle='#d8f36a';m.beginPath();m.arc(player.x/WORLD.w*r.width,player.y/WORLD.h*r.height,3,0,Math.PI*2);m.fill();}
}
function endMatch(){
  if(resultShown)return;resultShown=true;playing=false;mouse.down=false;
  const won=player.alive;$('#result').innerHTML=`<div class="result"><div class="result-card"><div class="eyebrow">${won?'LAST LIGHT STANDING':'MATCH COMPLETE'}</div><h2>${won?'VICTORY':'ELIMINATED'}</h2><p>${kills} ELIMINATIONS &nbsp; · &nbsp; ${remainingCount} OPERATORS LEFT</p><p class="result-note">${Math.floor(elapsed/60)}:${String(Math.floor(elapsed%60)).padStart(2,'0')} SURVIVED</p><button class="primary" id="again">PLAY AGAIN</button> &nbsp; <button class="secondary" id="back">LOBBY</button></div></div>`;
  $('#again').onclick=startGame;$('#back').onclick=exitGame;
}
function showPause(){
  if(!playing||resultShown)return;paused=!paused;mouse.down=false;const existing=$('#pause-overlay');if(existing){existing.remove();return;}
  const overlay=document.createElement('div');overlay.id='pause-overlay';overlay.className='pause-overlay';
  overlay.innerHTML='<div class="result-card"><div class="eyebrow">MATCH PAUSED</div><h2>TAKE A BREATHER.</h2><p>WASD / ARROWS MOVE · MOUSE AIM & FIRE</p><button class="primary" id="resume">RESUME MATCH</button><button class="secondary" id="pauseLobby">RETURN TO LOBBY</button></div>';
  $('#gameUI').appendChild(overlay);$('#resume').onclick=showPause;$('#pauseLobby').onclick=exitGame;
}
function exitGame(){playing=false;paused=false;mouse.down=false;cancelAnimationFrame(raf);$('#game').classList.add('hidden');$('#lobby').classList.remove('hidden');const overlay=$('#pause-overlay');if(overlay)overlay.remove();}
window.exitGame=exitGame;window.startGame=startGame;
function draw(){
  if(!W||!H||!player)return;
  ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(W/2-camera.x*scale,H/2-camera.y*scale);ctx.scale(scale,scale);
  ctx.fillStyle='#77966e';ctx.fillRect(0,0,WORLD.w,WORLD.h);
  for(let i=0;i<38;i++){ctx.fillStyle=i%2?'#809a70':'#7b956d';ctx.beginPath();ctx.ellipse((i*317+95)%2400,(i*197+60)%1600,90+(i%4)*19,42+(i%5)*13,i%7,0,Math.PI*2);ctx.fill();}
  ctx.strokeStyle='#4a9d9a';ctx.lineWidth=44;ctx.strokeRect(5,5,2390,1590);ctx.strokeStyle='#c9c19a';ctx.lineWidth=9;ctx.strokeRect(22,22,2356,1556);
  ctx.fillStyle='#428e91';ctx.beginPath();ctx.ellipse(1190,1300,180,105,-.2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#6fb8ae';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(1170,1290);ctx.bezierCurveTo(1050,1100,1390,1060,1250,850);ctx.bezierCurveTo(1200,700,1050,650,1100,500);ctx.stroke();
  ctx.fillStyle='#cfdbd0';ctx.beginPath();ctx.ellipse(1150,200,270,130,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f0eee3';for(let i=0;i<16;i++){ctx.beginPath();ctx.arc(990+i*21,170+(i%4)*19,13+(i%4)*3,0,Math.PI*2);ctx.fill();}
  ctx.fillStyle='#c2a878';ctx.beginPath();ctx.ellipse(2080,420,210,165,-.3,0,Math.PI*2);ctx.fill();
  ctx.lineCap='round';for(const [x1,y1,x2,y2]of roads){ctx.strokeStyle='#847f69';ctx.lineWidth=32;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.strokeStyle='#c7b995';ctx.lineWidth=24;ctx.stroke();}
  for(const t of trees){ctx.fillStyle=['#355844','#40674d','#507650','#597c54','#315742'][t.tone];ctx.beginPath();ctx.arc(t.x,t.y,t.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a1ad7188';ctx.beginPath();ctx.arc(t.x-t.r*.22,t.y-t.r*.3,t.r*.48,0,Math.PI*2);ctx.fill();}
  for(const b of buildings){ctx.fillStyle='#334a43';ctx.fillRect(b.x-b.w/2+4,b.y-b.h/2+5,b.w,b.h);ctx.fillStyle=b.c;ctx.fillRect(b.x-b.w/2,b.y-b.h/2,b.w,b.h);ctx.fillStyle=b.roof;ctx.fillRect(b.x-b.w/2+3,b.y-b.h/2+3,b.w-6,b.h-6);ctx.strokeStyle='#e2d7b574';ctx.lineWidth=1;ctx.strokeRect(b.x-b.w/2,b.y-b.h/2,b.w,b.h);ctx.fillStyle='#293c3c';ctx.fillRect(b.x-3,b.y-3,6,6);}

    // The storm curtain is drawn over the island but leaves the safe circle clear.
    if(zone.r<739){ctx.fillStyle='#704f7b55';ctx.beginPath();ctx.rect(0,0,WORLD.w,WORLD.h);ctx.arc(zone.x,zone.y,zone.r,0,Math.PI*2,true);ctx.fill('evenodd');ctx.strokeStyle='#c891e2';ctx.lineWidth=7;ctx.beginPath();ctx.arc(zone.x,zone.y,zone.r,0,Math.PI*2);ctx.stroke();}
    for(const l of loot)if(!l.taken){ctx.fillStyle=l.type==='med'?'#ff8b76':l.type==='armor'?'#69c8f2':'#d8f36a';ctx.save();ctx.translate(l.x,l.y);ctx.rotate(Math.PI/4);ctx.fillRect(-6,-6,12,12);ctx.restore();ctx.strokeStyle='#fff9';ctx.lineWidth=2;ctx.beginPath();ctx.arc(l.x,l.y,11,0,Math.PI*2);ctx.stroke();}
    for(const s of shots){ctx.strokeStyle=s.owner===player?'#fff5a6':'#ff906e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x-s.vx*.028,s.y-s.vy*.028);ctx.stroke();}
    for(const b of bots)if(b.alive)drawFighter(b,false);
    if(player.alive)drawFighter(player,true);
    ctx.restore();
  }
  function drawFighter(ent,isPlayer){
    ctx.save();ctx.translate(ent.x,ent.y);ctx.rotate(ent.angle);
    ctx.fillStyle='#15231f66';ctx.beginPath();ctx.ellipse(0,5,16,10,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle=isPlayer?'#d8f36a':'#ff7863';ctx.beginPath();ctx.ellipse(0,0,12,9,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle=isPlayer?'#274b46':'#442c2d';ctx.fillRect(-2,-6,11,12);ctx.fillStyle='#182328';ctx.fillRect(4,-2,18,4);
    ctx.fillStyle='#f6f1e7';ctx.beginPath();ctx.arc(4,-2,2,0,Math.PI*2);ctx.fill();ctx.restore();
    if(!isPlayer&&ent.hp<100){ctx.fillStyle='#15211e';ctx.fillRect(ent.x-12,ent.y-18,24,3);ctx.fillStyle='#ff8270';ctx.fillRect(ent.x-12,ent.y-18,24*ent.hp/100,3);}
    if(isPlayer&&ent.invuln>0){ctx.strokeStyle='#ffffffaa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(ent.x,ent.y,18,0,Math.PI*2);ctx.stroke();}
  }
  $('#start').onclick=startGame;
})();

