    const progress=clamp((elapsed-25)/65,0,1),targetR=740-progress*625;zone.r=Math.max(115,targetR);if(elapsed>25){zone.x=1200+Math.sin(elapsed*.025)*150;zone.y=800+Math.cos(elapsed*.021)*110;}
