    loot=loot.filter(l=>!l.taken);remainingCount=bots.filter(b=>b.alive).length+(player.alive?1:0);if(player.alive&&remainingCount===1)endMatch(true);if(Math.floor(elapsed*4)!==Math.floor((elapsed-dt)*4))updateHud();}
