  function drawMinimap(){const c=$('#minimap');if(!c)return;const r=c.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);}const g=c.getContext('2d');g.setTransform(d,0,0,d,0,0);g.clearRect(0,0,r.width,r.height);g.fillStyle='#526d58';g.fillRect(0,0,r.width,r.height);g.strokeStyle='#9bb098';g.lineWidth=1;for(const road of roads){g.beginPath();g.moveTo(road[0]/WORLD.w*r.width,road[1]/WORLD.h*r.height);g.lineTo(road[2]/WORLD.w*r.width,road[3]/WORLD.h*r.height);g.stroke();}g.strokeStyle='#74e8e4';g.beginPath();g.ellipse(zone.x/WORLD.w*r.width,zone.y/WORLD.h*r.height,zone.r/WORLD.w*r.width,zone.r/WORLD.h*r.height,0,0,Math.PI*2);g.stroke();for(const b of bots)if(b.alive){g.fillStyle='#ff7768';g.fillRect(b.x/WORLD.w*r.width-1,b.y/WORLD.h*r.height-1,2,2);}g.fillStyle='#d8f36a';g.beginPath();g.arc(player.x/WORLD.w*r.width,player.y/WORLD.h*r.height,3,0,Math.PI*2);g.fill();}
