node --input-type=module <<'NODE'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(runtime+'/package.json');
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(runtime+'/linux.json','utf8'));
if(!process.env.DISPLAY) process.env.DISPLAY=':'+readFileSync(runtime+'/display','utf8').trim();
const browser=await chromium.launch(config.browser.launchOptions);
const page=await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1});
page.on('pageerror',e=>console.error('PAGEERROR',e.message));
await page.goto('http://127.0.0.1:3000',{waitUntil:'load'});
await page.locator('#start').click();
await page.waitForTimeout(1400);
console.log('game visible',await page.locator('#game').isVisible(),'HUD',await page.locator('#alive').textContent(),'canvas',await page.locator('#world').evaluate(c=>[c.width,c.height]));
await page.screenshot({path:'/tmp/opencode/neon-tideline.jpg',type:'jpeg',quality:80});
await page.keyboard.press('Escape');
console.log('pause visible',await page.locator('#resume').isVisible());
await page.locator('#resume').click();
await page.waitForTimeout(200);
console.log('resumed',await page.locator('#resume').count()===0);
await browser.close();
