2:   const $=s=>document.querySelector(s), WORLD={w:2400,h:1600}, canvas=$('#world'), ctx=canvas.getContext('2d');
3:   let W=0,H=0,scale=1,raf=0,previous=0,playing=false,paused=false,resultShown=false,elapsed=0,kills=0,remainingCount=0;
