7:   function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);W=r.width;H=r.height;canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0);scale=clamp(Math.min(W/1000,H/650),.43,1);}
8:   new ResizeObserver(resize).observe(canvas);resize();
9:   function makeWorld(){trees=[];buildings=[];roads=[];const colors=[['#74816d','#a9a078'],['#687d6a','#9d9874'],['#907d60','#c0a979'],['#65837b','#9eb5a0']];
10:     for(let i=0;i<42;i++){const x=rand(130,2270),y=rand(120,1480);if((x<570&&y<480)||(x>1810&&y<510)||(x<460&&y>1170))continue;const p=colors[i%4];buildings.push({x,y,w:rand(60,125),h:rand(48,100),c:p[0],roof:p[1]});}
11:     for(let i=0;i<190;i++){const x=rand(50,2350),y=rand(55,1545);if(buildings.some(b=>Math.abs(x-b.x)<b.w*.7&&Math.abs(y-b.y)<b.h*.7))continue;trees.push({x,y,r:rand(8,19),tone:i%5});}
12:     roads=[[120,790,2280,790],[740,120,740,1480],[1580,120,1580,1480],[300,440,2100,440],[350,1160,2100,1160]];
13:   }
14:   function entity(x,y,isPlayer=false,id=0){return{x,y,hp:100,armor:isPlayer?25:0,alive:true,angle:0,speed:isPlayer?215:rand(92,125),fireCd:rand(.2,1.3),ammo:isPlayer?30:Infinity,reserve:isPlayer?120:0,meds:isPlayer?2:0,reload:0,invuln:0,id,isPlayer};}
15:   function buildUI(){
16:     $('#gameUI').innerHTML=`<div class="hudtop"><div class="hudbox healthbox"><div id="hptext">100 HP · 25 ARMOR</div><div class="bar"><i id="hpbar"></i></div><div class="bar armorbar"><i id="armorbar"></i></div></div><div class="hudcenter"><div id="phase">SAFE ZONE</div><strong id="zonetimer">00:25</strong></div><div class="hudbox weaponhud"><b><span id="ammotext">30</span> <small>/ <span id="reserve">120</span></small></b><div>BREAKWATER AR <span id="reloadtext"></span></div></div></div>
17:       <div class="mapbox"><canvas id="minimap"></canvas></div><div class="hudline"><span>OPERATORS <b id="alive">24</b></span><span>ELIMS <b id="killcount">0</b></span></div>
18:       <div class="bottomhud"><div class="hudbox itemhud">✚ <b id="medcount">2</b><small> MEDKITS · Q</small></div><button class="hudbox action-button" id="reloadBtn">R RELOAD</button><button class="hudbox action-button leave-match" id="leave">⏸ PAUSE</button></div>
19:       <div class="mobile-tip">WASD / ARROWS MOVE · CLICK OR HOLD TO FIRE · R RELOAD · Q MEDKIT · ESC PAUSE</div><div class="touch-controls"><div class="stick-zone" id="stick"><div class="stick-knob" id="knob"></div></div><div class="touch-actions"><button id="fireTouch">FIRE</button><button id="medTouch">MED</button></div></div><div id="toast" class="toast-message"></div><div id="result"></div>`;
20:     $('#leave').onclick=showPause;$('#reloadBtn').onclick=reload;$('#medTouch').onclick=useMed;$('#stick').onpointerdown=startStick;
21:     const fire=$('#fireTouch');fire.onpointerdown=e=>{e.preventDefault();mouse.down=true};fire.onpointerup=fire.onpointercancel=()=>mouse.down=false;
22:   }
23:   function startGame(){cancelAnimationFrame(raf);$('#modal').classList.add('hidden');$('#lobby').classList.add('hidden');$('#game').classList.remove('hidden');resize();buildUI();makeWorld();elapsed=0;kills=0;remainingCount=24;paused=false;resultShown=false;shots=[];loot=[];zone={x:1200,y:800,r:740};player=entity(1200+rand(-210,210),800+rand(-170,170),true);bots=[];
24:     for(let i=0;i<23;i++){const a=i/23*Math.PI*2,r=rand(320,680);bots.push(entity(clamp(1200+Math.cos(a)*r,45,2355),clamp(800+Math.sin(a)*r,45,1555),false,i+1));}
25:     camera={x:player.x,y:player.y};mouse.down=false;mouse.moved=false;playing=true;previous=performance.now();updateHud();draw();raf=requestAnimationFrame(loop);
26:   }
27:   function loop(now){const dt=Math.min(.05,Math.max(0,(now-previous)/1000));previous=now;update(dt);draw();if(playing)raf=requestAnimationFrame(loop);}
28:   function moveEntity(e,dx,dy){const nx=clamp(e.x+dx,35,WORLD.w-35),ny=clamp(e.y+dy,35,WORLD.h-35),blocked=buildings.some(b=>nx>b.x-b.w/2-13&&nx<b.x+b.w/2+13&&ny>b.y-b.h/2-13&&ny<b.y+b.h/2+13);if(!blocked){e.x=nx;e.y=ny;}else e.x=clamp(e.x+dx,35,WORLD.w-35);}
29:   function worldPoint(x,y){return{x:(x-W/2)/scale+camera.x,y:(y-H/2)/scale+camera.y};}
30:   function nearestOpponent(e,max=Infinity){let best=null,dist=max;for(const o of[player,...bots])if(o!==e&&o.alive){const d=Math.hypot(o.x-e.x,o.y-e.y);if(d<dist){dist=d;best=o;}}return best;}
31:   function shoot(e,target){if(!e.alive||e.fireCd>0)return;if(e.isPlayer&&e.ammo<=0){reload();return;}e.fireCd=e.isPlayer?.16:rand(.48,.82);if(e.isPlayer)e.ammo--;let a=e.angle;
32:     if(target&&target.alive&&!e.isPlayer)a=Math.atan2(target.y-e.y,target.x-e.x)+rand(-.16,.16);else if(e.isPlayer&&!mouse.moved&&target)a=Math.atan2(target.y-e.y,target.x-e.x);else if(e.isPlayer&&mouse.moved){const p=worldPoint(mouse.x,mouse.y);a=Math.atan2(p.y-e.y,p.x-e.x);}else a+=rand(-.055,.055);e.angle=a;
33:     const range=e.isPlayer?670:490;shots.push({x:e.x+Math.cos(a)*15,y:e.y+Math.sin(a)*15,vx:Math.cos(a)*760,vy:Math.sin(a)*760,life:range/760,owner:e,damage:e.isPlayer?26:10});}
34:   function hit(e,damage,owner){if(!e.alive||e.invuln>0)return;const absorbed=Math.min(e.armor,damage*.65);e.armor-=absorbed;e.hp-=damage-absorbed;e.invuln=.07;if(e.hp<=0){e.hp=0;e.alive=false;if(e===player)endMatch();else{remainingCount--;if(owner===player)kills++;dropLoot(e.x,e.y);}}}
35:   function dropLoot(x,y){loot.push({x:x+rand(-12,12),y:y+rand(-12,12),type:['ammo','armor','med'][Math.floor(rand(0,3))],taken:false});}
36:   function toast(text){const e=$('#toast');if(e){e.textContent=text;e.classList.add('show');toastTimer=1.5;}}
37:   function reload(){if(player&&player.ammo<30&&player.reserve>0&&player.reload<=0){player.reload=1.15;mouse.down=false;}}
38:   function useMed(){if(player&&player.meds>0&&player.hp<100){player.meds--;player.hp=Math.min(100,player.hp+38);toast('MEDKIT USED');updateHud();}}
39:   function startStick(e){e.preventDefault();const el=$('#stick');touch.id=e.pointerId;el.setPointerCapture(e.pointerId);updateStick(e,el.getBoundingClientRect());}
40:   function updateStick(e,r){const dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),m=Math.min(1,39/(len||1));touch.x=dx*m/39;touch.y=dy*m/39;touch.active=true;const k=$('#knob');if(k)k.style.transform=`translate(${touch.x*39}px,${touch.y*39}px)`;}
41:   document.addEventListener('pointermove',e=>{if(touch.id===e.pointerId)updateStick(e,$('#stick').getBoundingClientRect());});
42:   document.addEventListener('pointerup',e=>{if(touch.id===e.pointerId){touch.id=null;touch.active=false;touch.x=touch.y=0;const k=$('#knob');if(k)k.style.transform='translate(0,0)';}});
43:   canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top;if(e.pointerType==='mouse')mouse.moved=true;});
44:   canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){mouse.down=true;canvas.setPointerCapture(e.pointerId);}});
