input.content:
import { spawn } from 'node:child_process';
import { setTimeout as delay } from 'node:timers/promises';
const browser=spawn('/usr/bin/chromium',['--headless=new','--no-sandbox','--disable-gpu','--remote-allow-origins=*','--remote-debugging-port=9222','--user-data-dir=/tmp/opencode/chrome-neon','--window-size=1280,720','http://127.0.0.1:3000'],{stdio:'ignore'});
let ws;
try {
  let page;
  for(let i=0;i<80;i++) { try { const r=await fetch('http://127.0.0.1:9222/json'); const tabs=await r.json(); page=tabs.find(x=>x.type==='page'); if(page)break; } catch {} await delay(250); }
  if(!page) throw Error('Chromium page did not start');
  ws=new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject;});
  let id=0; const pending=new Map(), errors=[];
  ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(m.error.message)):p.resolve(m.result);}else if(m.method==='Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.text);};
  const send=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}));});
  await send('Page.enable'); await send('Runtime.enable');
  const evalJs=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.value;
  await delay(700);
  await evalJs("document.querySelector('#start').click()"); await delay(1100);
  const startState=await evalJs("({gameVisible:!document.querySelector('#game').classList.contains('hidden'),gameTop:document.querySelector('#game').getBoundingClientRect().top,gameHeight:document.querySelector('#game').getBoundingClientRect().height,topbar:document.querySelector('.topbar').getBoundingClientRect().top,players:document.querySelector('#alive').textContent,canvas:!!document.querySelector('#world').getContext('2d')})");
  await evalJs("document.querySelector('#leave').click()"); await delay(150);
  const paused=await evalJs("document.querySelector('#result').textContent.includes('MATCH PAUSED')");
  await evalJs("document.querySelector('#resume').click()"); await delay(250);
  const resumed=await evalJs("document.querySelector('#result').innerHTML==='' ");
  const shot=await send('Page.captureScreenshot',{format:'jpeg',quality:82,fromSurface:true});
  await import('node:fs/promises').then(fs=>fs.writeFile('/tmp/opencode/neon-tideline.jpg',Buffer.from(shot.data,'base64')));
  console.log(JSON.stringify({startState,paused,resumed,errors},null,2));
} finally { ws?.close(); browser.kill('SIGTERM'); }

